changeSet.sql:
ALTER TABLE competitions
DROP CONSTRAINT IF EXISTS chk_competitions_status;

ALTER TABLE competitions
  ADD CONSTRAINT chk_competitions_status
    CHECK (competition_status IN ('DRAFT', 'PUBLISHED', 'ENROLLMENT', 'FINISHED', 'ARCHIVED'));

ALTER TABLE stages
DROP CONSTRAINT IF EXISTS chk_stages_scope;

ALTER TABLE stages
  ADD CONSTRAINT chk_stages_scope
    CHECK (scope IN ('NATIONAL', 'REGIONAL', 'CITY', 'DISTRICT', 'FOREIGN', 'OPEN'));
